/// <summary>
/// 字典数据种子数据初始化
/// 幂等性操作：存在则更新，不存在则创建
/// 租户级；CultureCode 默认 Localization:MultiCultureCode（mul=多种语言内容，ISO 639-3）；zh-CN/ja-JP 仅税码/税率/财年等区域项；sys_culture_code 与 sys_*_status 用通用码
/// sys_culture_code：仅 UI 支持 EN-US/JA-JP/ZH-CN/ZH-HK 保持启用，其余历史项 IsDeleted=1
/// </summary>
public class TaktDictDataSeedData : ITaktSeedDataCoordinator
{
    /// <summary>
    /// 前端 UI / TaktCultureSeedData 当前支持的区域文化 DictValue（大写 BCP47）
    /// </summary>
    private static readonly HashSet<string> UiSupportedCultureDictValues = new(StringComparer.OrdinalIgnoreCase)
    {
        "EN-US",
        "JA-JP",
        "ZH-CN",
        "ZH-HK",
    };

    /// <summary>
    /// 编码规则重置周期标准 DictValue（sys_reset_period）
    /// </summary>
    private static readonly HashSet<string> SupportedResetPeriodDictValues = new(StringComparer.OrdinalIgnoreCase)
    {
        "None",
        "Annually",
        "Monthly",
        "Daily",
    };

    /// <summary>
    /// 发布范围标准 DictValue（sys_publish_scope；不含指定角色）
    /// </summary>
    private static readonly HashSet<string> SupportedPublishScopeDictValues = new(StringComparer.OrdinalIgnoreCase)
    {
        "0",
        "1",
        "2",
    };

    /// <summary>
    /// 执行顺序（在 DictType 之后）
    /// </summary>
    public int Order => 46;

    /// <summary>
    /// 初始化字典数据种子数据
    /// </summary>
    /// <param name="serviceProvider">服务提供者</param>
    /// <param name="tenantCode">租户编码（由协调器传入）</param>
    /// <returns>返回插入和更新的记录数（插入数, 更新数）</returns>
    public async Task<(int InsertCount, int UpdateCount)> SeedAsync(IServiceProvider serviceProvider, string? tenantCode = null)
    {
        TaktLogger.Information("开始初始化字典数据种子数据...");

        // 参数验证
        if (string.IsNullOrEmpty(tenantCode))
        {
            TaktLogger.Warning("租户编码为空，跳过字典数据种子数据初始化");
            return (0, 0);
        }

        var dictDataRepository = serviceProvider.GetRequiredService<ITaktTenantSeedRepository<TaktDictData>>();
        var dictTypeRepository = serviceProvider.GetRequiredService<ITaktTenantSeedRepository<TaktDictType>>();
        var seedContext = serviceProvider.GetRequiredService<TaktSeedContext>();
        var multiCultureCode = serviceProvider.GetRequiredService<IConfiguration>().RequireLocalization().MultiCultureCode;
        var dictTypeIdByCode = await LoadDictTypeIdCacheAsync(dictTypeRepository, tenantCode);

        int insertCount = 0;
        int updateCount = 0;

        TaktLogger.Information("正在为租户 {TenantCode} 初始化字典数据...", tenantCode);

        // 为当前租户初始化标准字典数据
        var dictDataList = GetStandardDictData();
        foreach (var dictDataItem in dictDataList)
        {
            var dictTypeCode = NormalizeDictTypeCode(dictDataItem.DictTypeCode);
            if (!dictTypeIdByCode.ContainsKey(dictTypeCode))
            {
                TaktLogger.Warning(
                    "字典类型不存在，跳过字典数据: TenantCode={TenantCode}, DictTypeCode={DictTypeCode}, DictValue={DictValue}",
                    tenantCode,
                    dictTypeCode,
                    dictDataItem.DictValue);
                continue;
            }

            var (_, isInserted) = await CreateOrUpdateDictDataAsync(
                dictDataRepository,
                seedContext,
                dictTypeIdByCode,
                tenantCode,
                ResolveDictCultureCode(dictDataItem.CultureCode, multiCultureCode),
                dictTypeCode,
                dictDataItem.DictLabel,
                dictDataItem.DictValue,
                dictDataItem.I18nKey,
                dictDataItem.ListClass,
                dictDataItem.CssClass,
                dictDataItem.IsDefault,
                dictDataItem.Remark,
                dictDataItem.SortOrder,
                string.IsNullOrEmpty(dictDataItem.ExtLabel) ? null : dictDataItem.ExtLabel,
                string.IsNullOrEmpty(dictDataItem.ExtValue) ? null : dictDataItem.ExtValue);

            insertCount += (isInserted ? 1 : 0);
            updateCount += (isInserted ? 0 : 1);
        }

        var softDeletedCultures = await SoftDeleteUnsupportedCultureCodesAsync(seedContext, tenantCode);
        if (softDeletedCultures > 0)
        {
            TaktLogger.Information(
                "sys_culture_code 非 UI 支持项已软删除 {Count} 条（仅保留 EN-US/JA-JP/ZH-CN/ZH-HK）",
                softDeletedCultures);
        }

        var softDeletedResetPeriods = await SoftDeleteUnsupportedResetPeriodsAsync(seedContext, tenantCode);
        if (softDeletedResetPeriods > 0)
        {
            TaktLogger.Information(
                "sys_reset_period 非标准项已软删除 {Count} 条（仅保留 None|Annually|Monthly|Daily）",
                softDeletedResetPeriods);
        }

        var softDeletedPublishScopes = await SoftDeleteUnsupportedPublishScopesAsync(seedContext, tenantCode);
        if (softDeletedPublishScopes > 0)
        {
            TaktLogger.Information(
                "sys_publish_scope 非标准项已软删除 {Count} 条（仅保留 0|1|2，不含指定角色）",
                softDeletedPublishScopes);
        }

        var softDeletedEcScopes = await SoftDeleteObsoleteEcScopeCategoriesAsync(seedContext, tenantCode);
        if (softDeletedEcScopes > 0)
        {
            TaktLogger.Information(
                "logistics_manufacturing_ec_scope_category 非标准项已软删除 {Count} 条（仅保留 1=全仕向 2=部管 3=内部 4=技术）",
                softDeletedEcScopes);
        }

        TaktLogger.Information("字典数据种子数据初始化完成: 插入 {InsertCount} 条，更新 {UpdateCount} 条", insertCount, updateCount);

        return (insertCount, updateCount);
    }

