    /// <summary>
    /// 加载当前租户字典类型编码与 ID 映射（DictType 种子 Order=45，本类 Order=46，类型已就绪）
    /// </summary>
    /// <param name="dictTypeRepository">字典类型仓储</param>
    /// <param name="tenantCode">租户编码</param>
    /// <returns>DictTypeCode → DictTypeId</returns>
    private static async Task<Dictionary<string, long>> LoadDictTypeIdCacheAsync(
        ITaktTenantSeedRepository<TaktDictType> dictTypeRepository,
        string tenantCode)
    {
        var dictTypes = await dictTypeRepository.GetListAsync(d => d.TenantCode == tenantCode);
        var dictTypeIdByCode = new Dictionary<string, long>(StringComparer.OrdinalIgnoreCase);
        foreach (var dictType in dictTypes)
        {
            var code = NormalizeDictTypeCode(dictType.DictTypeCode);
            if (string.IsNullOrEmpty(code))
            {
                continue;
            }

            if (!dictTypeIdByCode.ContainsKey(code)
                || string.Equals(dictType.DictTypeCode, code, StringComparison.Ordinal))
            {
                dictTypeIdByCode[code] = dictType.Id;
            }
        }

        return dictTypeIdByCode;
    }

    /// <summary>
    /// 规范化 DictTypeCode：去除零宽字符与首尾空白，避免种子码与库内码表面不一致
    /// </summary>
    /// <param name="dictTypeCode">字典类型编码</param>
    /// <returns>规范化后的编码；空输入返回空串</returns>
    private static string NormalizeDictTypeCode(string? dictTypeCode)
    {
        if (string.IsNullOrWhiteSpace(dictTypeCode))
        {
            return string.Empty;
        }

        return dictTypeCode
            .Replace("\u200B", string.Empty)
            .Replace("\u200C", string.Empty)
            .Replace("\u200D", string.Empty)
            .Replace("\uFEFF", string.Empty)
            .Trim();
    }

    /// <summary>
    /// 解析字典行 CultureCode：空或种子哨兵 mul → Localization:MultiCultureCode；否则保留区域码（如 zh-CN）
    /// </summary>
    /// <param name="cultureCode">种子行文化码</param>
    /// <param name="multiCultureCode">配置的多种语言内容通用码</param>
    /// <returns>写入库的 CultureCode</returns>
    private static string ResolveDictCultureCode(string cultureCode, string multiCultureCode)
    {
        if (string.IsNullOrWhiteSpace(cultureCode)
            || string.Equals(cultureCode.Trim(), TaktLocalizationOptions.DefaultMultiCultureCode, StringComparison.OrdinalIgnoreCase))
        {
            return multiCultureCode;
        }

        return cultureCode.Trim();
    }

    /// <summary>
    /// 按字典类型编码解析 DictTypeId
    /// </summary>
    /// <param name="dictTypeIdByCode">字典类型编码缓存</param>
    /// <param name="tenantCode">租户编码</param>
    /// <param name="dictTypeCode">字典类型编码</param>
    /// <returns>字典类型 ID</returns>
    private static long ResolveDictTypeId(
        Dictionary<string, long> dictTypeIdByCode,
        string tenantCode,
        string dictTypeCode)
    {
        if (!dictTypeIdByCode.TryGetValue(NormalizeDictTypeCode(dictTypeCode), out var dictTypeId))
        {
            throw new InvalidOperationException(
                $"字典类型不存在，无法初始化字典数据: TenantCode={tenantCode}, DictTypeCode={dictTypeCode}");
        }
        return dictTypeId;
    }

    /// <summary>
    /// 创建或更新字典数据（幂等键：租户+类型编码+CultureCode+DictValue）
    /// sys_culture_code 查询含已软删除行，便于恢复 UI 支持项
    /// </summary>
    /// <param name="repository">字典数据仓储</param>
    /// <param name="seedContext">种子上下文（含 SqlSugar，用于含删除查询）</param>
    /// <param name="dictTypeIdByCode">字典类型编码缓存</param>
    /// <param name="tenantCode">租户编码</param>
    /// <param name="cultureCode">区域文化编码</param>
    /// <param name="dictTypeCode">字典类型编码</param>
    /// <param name="dictLabel">字典标签</param>
    /// <param name="dictValue">字典值</param>
    /// <param name="i18nKey">国际化键</param>
    /// <param name="listClass">列表样式类</param>
    /// <param name="cssClass">CSS类名</param>
    /// <param name="isDefault">是否默认项</param>
    /// <param name="remark">备注</param>
    /// <param name="sortOrder">排序</param>
    /// <param name="extLabel">扩展标签（如国家英文名；可空）</param>
    /// <param name="extValue">扩展值（如国家 JSON：phoneCode/currencyCode/language；可空）</param>
    /// <returns>(字典数据实体, 是否为新插入)</returns>
    private static async Task<(TaktDictData DictData, bool IsInserted)> CreateOrUpdateDictDataAsync(
        ITaktTenantSeedRepository<TaktDictData> repository,
        TaktSeedContext seedContext,
        Dictionary<string, long> dictTypeIdByCode,
        string tenantCode,
        string cultureCode,
        string dictTypeCode,
        string dictLabel,
        string dictValue,
        string i18nKey,
        int listClass,
        int cssClass,
        int isDefault,
        string remark,
        int sortOrder,
        string? extLabel = null,
        string? extValue = null)
    {
        var dictTypeId = ResolveDictTypeId(dictTypeIdByCode, tenantCode, dictTypeCode);
        var culture = string.IsNullOrWhiteSpace(cultureCode)
            ? TaktLocalizationOptions.DefaultMultiCultureCode
            : cultureCode.Trim();
        TaktDictData? dictData;
        if (string.Equals(dictTypeCode, "sys_culture_code", StringComparison.OrdinalIgnoreCase))
        {
            // 含已软删除：避免唯一索引冲突，并可恢复 UI 支持项
            dictData = await seedContext.Db.Queryable<TaktDictData>()
                .Where(d =>
                    d.TenantCode == tenantCode &&
                    d.DictTypeCode == dictTypeCode &&
                    d.CultureCode == culture &&
                    d.DictValue == dictValue)
                .FirstAsync();
        }
        else
        {
            dictData = await repository.FirstAsync(d =>
                d.TenantCode == tenantCode &&
                d.DictTypeCode == dictTypeCode &&
                d.CultureCode == culture &&
                d.DictValue == dictValue);
        }

        if (dictData == null)
        {
            dictData = new TaktDictData
            {
                TenantCode = tenantCode,
                DictTypeId = dictTypeId,
                DictTypeCode = dictTypeCode,
                CultureCode = culture,
                DictLabel = dictLabel,
                DictValue = dictValue,
                I18nKey = i18nKey,
                ExtLabel = extLabel,
                ExtValue = extValue,
                ListClass = listClass,
                CssClass = cssClass,
                IsDefault = isDefault,
                Remark = remark,
                SortOrder = sortOrder
            };
            dictData = await repository.CreateAsync(dictData);
            return (dictData, true);
        }

        dictData.DictTypeId = dictTypeId;
        dictData.DictTypeCode = dictTypeCode;
        dictData.CultureCode = culture;
        dictData.DictLabel = dictLabel;
        dictData.I18nKey = i18nKey;
        dictData.ExtLabel = extLabel;
        dictData.ExtValue = extValue;
        dictData.ListClass = listClass;
        dictData.CssClass = cssClass;
        dictData.IsDefault = isDefault;
        dictData.Remark = remark;
        dictData.SortOrder = sortOrder;
        // UI 支持的区域文化保持启用；Create 后若曾软删除则恢复
        if (string.Equals(dictTypeCode, "sys_culture_code", StringComparison.OrdinalIgnoreCase)
            && UiSupportedCultureDictValues.Contains(dictValue))
        {
            dictData.IsDeleted = 0;
            dictData.DeletedAt = null;
            dictData.DeletedBy = null;
        }

        await repository.UpdateAsync(dictData);
        return (dictData, false);
    }

    /// <summary>
    /// 将非 UI 支持的 sys_culture_code 项软删除（IsDeleted=1）
    /// </summary>
    /// <param name="seedContext">种子上下文</param>
    /// <param name="tenantCode">租户编码</param>
    /// <returns>软删除条数</returns>
    private static async Task<int> SoftDeleteUnsupportedCultureCodesAsync(
        TaktSeedContext seedContext,
        string tenantCode)
    {
        var now = DateTime.Now;
        var supported = UiSupportedCultureDictValues.ToArray();
        return await seedContext.Db.Updateable<TaktDictData>()
            .SetColumns(d => new TaktDictData
            {
                IsDeleted = 1,
                UpdatedAt = now,
                DeletedAt = now,
            })
            .Where(d =>
                d.TenantCode == tenantCode &&
                d.DictTypeCode == "sys_culture_code" &&
                d.IsDeleted == 0 &&
                !supported.Contains(d.DictValue))
            .ExecuteCommandAsync();
    }

